(function () {
  "use strict";

  var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  /* ---------- Hero video cycler: three clips, 5 seconds each ---------- */
  var videos = Array.prototype.slice.call(document.querySelectorAll(".hero-video"));
  var bars = Array.prototype.slice.call(document.querySelectorAll(".clip-bar"));
  var CLIP_SECONDS = 5;
  var FADE_LEAD = 0.85; // start crossfade this many seconds before the end
  var current = 0;
  var switching = false;
  var rafId = null;

  function setBar(index, progress) {
    bars[index].querySelector("span").style.setProperty("--p", String(progress));
  }

  function markActiveBar(index) {
    bars.forEach(function (bar, i) {
      bar.setAttribute("aria-selected", i === index ? "true" : "false");
      if (i !== index) setBar(i, i < index ? 1 : 0);
    });
  }

  function goTo(next) {
    if (switching || next === current) return;
    switching = true;
    var prev = current;
    current = next;

    var v = videos[next];
    v.currentTime = 0;
    var p = v.play();
    if (p && p.catch) p.catch(function () {});
    v.classList.add("is-active");
    videos[prev].classList.remove("is-active");
    markActiveBar(next);

    setTimeout(function () {
      videos[prev].pause();
      switching = false;
    }, 950);
  }

  function tick() {
    var v = videos[current];
    var limit = Math.min(v.duration || CLIP_SECONDS, CLIP_SECONDS);
    if (v.currentTime > 0) setBar(current, Math.min(v.currentTime / limit, 1));
    if (!switching && v.currentTime >= limit - FADE_LEAD) {
      goTo((current + 1) % videos.length);
    }
    rafId = requestAnimationFrame(tick);
  }

  function startHero() {
    var first = videos[0].play();
    if (first && first.catch) first.catch(function () {});
    markActiveBar(0);
    rafId = requestAnimationFrame(tick);
  }

  if (videos.length && bars.length) {
    if (reduceMotion) {
      // Static poster, filled bars, no autoplay.
      bars.forEach(function (_, i) { setBar(i, i === 0 ? 1 : 0); });
    } else {
      startHero();

      bars.forEach(function (bar, i) {
        bar.addEventListener("click", function () { goTo(i); });
      });

      // Pause the loop when the hero is off screen; resume when back.
      var heroObserver = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            var p = videos[current].play();
            if (p && p.catch) p.catch(function () {});
            if (rafId === null) rafId = requestAnimationFrame(tick);
          } else {
            videos[current].pause();
            if (rafId !== null) { cancelAnimationFrame(rafId); rafId = null; }
          }
        });
      }, { threshold: 0.05 });
      heroObserver.observe(document.querySelector(".hero"));
    }
  }

  /* ---------- Nav glass state (sentinel, no scroll listener) ---------- */
  var nav = document.getElementById("nav");
  var sentinel = document.getElementById("nav-sentinel");
  if (nav && sentinel) {
    new IntersectionObserver(function (entries) {
      nav.classList.toggle("scrolled", !entries[0].isIntersecting);
    }, { rootMargin: "80px 0px 0px 0px" }).observe(sentinel);
  }

  /* ---------- Count-up on the proof numbers ---------- */
  var counts = document.querySelectorAll(".count");
  if (counts.length && !reduceMotion && "IntersectionObserver" in window) {
    var countUp = function (el) {
      var target = parseFloat(el.getAttribute("data-target"));
      var decimals = parseInt(el.getAttribute("data-decimals") || "0", 10);
      var duration = 1100;
      var start = null;
      var step = function (ts) {
        if (start === null) start = ts;
        var t = Math.min((ts - start) / duration, 1);
        var eased = 1 - Math.pow(1 - t, 3);
        el.textContent = (target * eased).toFixed(decimals);
        if (t < 1) requestAnimationFrame(step);
      };
      requestAnimationFrame(step);
    };
    var countObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          countUp(entry.target);
          countObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.6 });
    counts.forEach(function (el) { countObserver.observe(el); });
  }

  /* ---------- Word-by-word title reveals ----------
     Split display headings into word spans; the existing reveal observer
     then cascades them via the .reveal.in .word rule. Skipped entirely under
     reduced motion, so the headings stay plain text there. */
  if (!reduceMotion) {
    var splitTargets = document.querySelectorAll(".section-title, .visit-copy h2");
    splitTargets.forEach(function (el) {
      var text = el.textContent.trim();
      el.setAttribute("aria-label", text); // spans stay visual-only
      el.textContent = "";
      text.split(/\s+/).forEach(function (word, i, arr) {
        var span = document.createElement("span");
        span.className = "word";
        span.setAttribute("aria-hidden", "true");
        span.style.transitionDelay = (i * 0.06) + "s";
        span.textContent = word;
        el.appendChild(span);
        if (i < arr.length - 1) el.appendChild(document.createTextNode(" "));
      });
      el.classList.add("is-split");
    });
  }

  /* ---------- Scroll reveals ---------- */
  var revealEls = document.querySelectorAll(".reveal");
  if (reduceMotion) {
    revealEls.forEach(function (el) { el.classList.add("in"); });
  } else {
    var revealObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add("in");
          revealObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.18, rootMargin: "0px 0px -40px 0px" });
    revealEls.forEach(function (el) { revealObserver.observe(el); });
  }
})();
